import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import {createRequire} from 'node:module';
import {pathToFileURL} from 'node:url';
import {createHash} from 'node:crypto';
const root=path.resolve(process.argv[2]||process.cwd());
const require=createRequire(path.join(root,'package.json'));
const {chromium}=require('playwright');
const sha=b=>createHash('sha256').update(b).digest('hex');
const source=await fs.readFile(path.join(root,'index.html'));
const expected=process.env.EVA_EXPECTED_SHA;
if(expected&&sha(source)!==expected)throw new Error('Input hash mismatch');
const temporary=await fs.mkdtemp(path.join(os.tmpdir(),'eva-profile-confirmation-'));
const input=path.join(temporary,'index.html');await fs.writeFile(input,source);
const output=path.join(root,'..','qa-baseline','quality-confirmation-results.json');
const report={startedAt:new Date().toISOString(),inputSha256:sha(source),purpose:'Targeted verification of the five profile commits after fixing a QA frame-count race. No other integration scenario or timing sample is repeated.',method:'A change listener registered after the application listener records the frame counter at the actual quality commit. Each observation waits for a strictly newer completed application frame.',runnerSha256:sha(await fs.readFile(path.join(root,'tests/browser.mjs'))),playwrightVersion:require('playwright/package.json').version,viewport:{width:640,height:520},profiles:[],errors:[],warnings:[],externalRequests:[],browserClosed:false};
let browser;
const poll=async(page,predicate,arg,timeout=45000)=>{const until=Date.now()+timeout;do{if(await page.evaluate(predicate,arg))return;await page.waitForTimeout(100);}while(Date.now()<until);throw new Error('Timed out waiting for targeted profile condition');};
try{
 const args=['--no-sandbox','--disable-dev-shm-usage'];if(process.env.EVA_SOFTWARE_RENDERER==='1')args.push('--use-angle=swiftshader','--enable-unsafe-swiftshader');
 browser=await chromium.launch({headless:true,args,...(process.env.EVA_BROWSER_EXECUTABLE?{executablePath:process.env.EVA_BROWSER_EXECUTABLE}:{})});report.browserVersion=browser.version();
 const context=await browser.newContext({viewport:report.viewport,deviceScaleFactor:1,serviceWorkers:'block'});
 await context.route('**/*',async route=>{const url=route.request().url();if(/^https?:/.test(url)){report.externalRequests.push(url);await route.abort('blockedbyclient');}else await route.continue();});await context.setOffline(true);
 await context.addInitScript(()=>{window.__QA_REQUESTS__=0;Object.defineProperty(navigator.mediaDevices,'getUserMedia',{configurable:true,value:async()=>{window.__QA_REQUESTS__++;throw new DOMException('Denied targeted QA fixture','NotAllowedError');}});});
 const page=await context.newPage();page.setDefaultTimeout(25000);
 page.on('pageerror',e=>report.errors.push(String(e)));page.on('console',m=>{if(m.type()==='error')report.errors.push(m.text());if(m.type()==='warning')report.warnings.push(m.text());});
 await page.goto(pathToFileURL(input).href);await poll(page,()=>window.__DIORAMA__?.ready,undefined,120000);
 if(await page.locator('#welcomePanel').isVisible())await page.locator('#welcomeExploreButton').click();
 await page.evaluate(()=>window.__DIORAMA__.pause(true));await poll(page,()=>!window.__DIORAMA__.getState().renderScheduled);
 await page.locator('#settingsButton').click();
 const expectedFeatures={performance:[false,false],balanced:[true,false],quality:[true,true],ultra:[true,true],cinematic:[true,true]};
 for(const [profile,[bloom,ao]]of Object.entries(expectedFeatures)){
  await page.evaluate(()=>{window.__EVA_QA_QUALITY_COMMIT__=null;document.getElementById('quality').addEventListener('change',()=>{const s=window.__DIORAMA__.getState();window.__EVA_QA_QUALITY_COMMIT__={profile:s.quality,frames:s.frames};},{once:true});});
  await page.locator('#quality').selectOption(profile);
  await poll(page,p=>{const d=window.__DIORAMA__.getState(),c=window.__EVA_QA_QUALITY_COMMIT__;return c?.profile===p&&d.quality===p&&d.frames>c.frames;},profile);
  const observed=await page.evaluate(()=>{const d=window.__DIORAMA__,s=d.getState();return{profile:s.quality,committedAtFrame:window.__EVA_QA_QUALITY_COMMIT__.frames,observedAtFrame:s.frames,buffer:{width:d.renderer.domElement.width,height:d.renderer.domElement.height},dpr:s.viewport.dpr,effectiveQuality:s.effectiveQuality,hdr:s.hdr,bloom:s.bloomActive,ao:s.aoActive,aa:s.aaMethod,photo:s.photoMode,paused:s.paused,drawCalls:s.drawCalls,triangles:s.triangles,geometries:s.geometries,textures:s.textures,programs:s.programs,maxTextureSize:s.capabilities.limits.maxTextureSize,renderer:s.capabilities.rendererName,preferences:s.preferences};});
  observed.checks={completedAfterCommit:observed.observedAtFrame>observed.committedAtFrame,profile:observed.profile===profile&&observed.preferences.quality===profile,effects:observed.bloom===Boolean(observed.hdr&&observed.preferences.bloom&&bloom)&&observed.ao===Boolean(observed.hdr&&observed.preferences.ao&&ao),budget:observed.effectiveQuality.bloom===bloom&&observed.effectiveQuality.ao===ao,buffer:observed.buffer.width>0&&observed.buffer.height>0&&observed.buffer.width<=observed.maxTextureSize&&observed.buffer.height<=observed.maxTextureSize&&observed.dpr>0&&observed.dpr<=observed.effectiveQuality.maxPixelRatio+.001&&observed.buffer.width*observed.buffer.height<=observed.effectiveQuality.pixelBudget+observed.buffer.width+observed.buffer.height,photo:observed.paused&&observed.photo===(profile==='cinematic')};
  observed.pass=Object.values(observed.checks).every(Boolean);report.profiles.push(observed);console.log(JSON.stringify({profile,pass:observed.pass,committedAtFrame:observed.committedAtFrame,observedAtFrame:observed.observedAtFrame,drawCalls:observed.drawCalls,triangles:observed.triangles}));
  if(!observed.pass)throw new Error('Targeted profile assertions failed: '+profile);
 }
 report.cameraRequests=await page.evaluate(()=>window.__QA_REQUESTS__);report.passed=report.profiles.length===5&&report.profiles.every(p=>p.pass)&&report.errors.length===0&&report.externalRequests.length===0&&report.cameraRequests===0;
}catch(error){report.failure=error.stack||String(error);report.passed=false;process.exitCode=1;}
finally{if(browser)await browser.close();report.browserClosed=true;report.finishedAt=new Date().toISOString();report.sourceStillMatches=sha(await fs.readFile(path.join(root,'index.html')))===report.inputSha256;await fs.writeFile(output,JSON.stringify(report,null,2)+'\n');await fs.rm(temporary,{recursive:true,force:true});console.log(JSON.stringify({passed:report.passed,browserClosed:true,output,failure:report.failure||null}));}
